-- =====================================================================
-- PowerX Nutrition — Supabase STORAGE setup (run once in Supabase → SQL Editor)
--
-- Tables are NOT created here any more: the app creates and upgrades them automatically
-- on first start (see supabase/migrations/*.sql, generated by `npm run db:export-sql`).
-- If you used the old version (px_products / px_orders tables), the app imports that data
-- into the new tables automatically the first time it starts on an empty database.
-- =====================================================================

-- Public bucket: APPROVED product photos (shown on the website)
insert into storage.buckets (id, name, public)
values ('product-images', 'product-images', true)
on conflict (id) do nothing;

-- PRIVATE bucket: supplier invoices & expense receipts (only the server can read them)
insert into storage.buckets (id, name, public)
values ('private-files', 'private-files', false)
on conflict (id) do nothing;
